public List<String> solve(String s) {
    List<String> res = new ArrayList<>();
    permute(s.toCharArray(), 0, res);
    Collections.sort(res);
    return res;
}
private void permute(char[] arr, int idx, List<String> res) {
    if (idx == arr.length) { res.add(new String(arr)); return; }
    for (int i = idx; i < arr.length; i++) {
        char t = arr[idx]; arr[idx] = arr[i]; arr[i] = t;
        permute(arr, idx + 1, res);
        t = arr[idx]; arr[idx] = arr[i]; arr[i] = t;
    }
}

