vector<vector<string>> solve(string s) {
    vector<vector<string>> res;
    vector<string> path;
    auto is_pal = [](const string& sub) { int l=0, r=(int)sub.size()-1; while(l<r) if(sub[l++]!=sub[r--]) return false; return true; };
    auto backtrack = [&](auto& self, int start) -> void {
        if(start == (int)s.size()) { res.push_back(path); return; }
        for(int end = start + 1; end <= (int)s.size(); ++end) {
            string sub = s.substr(start, end - start);
            if(is_pal(sub)) { path.push_back(sub); self(self, end); path.pop_back(); }
        }
    };
    backtrack(backtrack, 0);
    return res;
}

