function solve(s) {
    const res = [];
    const isPal = sub => sub === sub.split('').reverse().join('');
    function backtrack(start, path) {
        if (start === s.length) { res.push([...path]); return; }
        for (let end = start + 1; end <= s.length; end++) {
            const sub = s.slice(start, end);
            if (isPal(sub)) { path.push(sub); backtrack(end, path); path.pop(); }
        }
    }
    backtrack(0, []);
    return res;
}

